mkdir -p /app/output/assets && cat > /app/output/assets/styles.css <<'CSS'
:root {
  --bg: #081421;
  --bg-2: #0d1b2a;
  --panel: #102236;
  --panel-2: #15295a;
  --line: rgba(156, 201, 255, .16);
  --text: #ecf6ff;
  --muted: #9fb2c7;
  --blue: #00b4d8;
  --blue-2: #0077b6;
  --green: #6cc24a;
  --gray: #3c424b;
  --shadow: 0 24px 80px rgba(0, 0, 0, .32);
  --radius: 24px;
  --max: 1180px;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background:
    radial-gradient(circle at 18% -12%, rgba(0, 180, 216, .22), transparent 34rem),
    radial-gradient(circle at 82% 8%, rgba(108, 194, 74, .13), transparent 30rem),
    linear-gradient(180deg, #081421 0%, #0d1b2a 48%, #07111d 100%);
  color: var(--text);
  line-height: 1.6;
}

a { color: inherit; text-decoration: none; }
button, input, select, textarea { font: inherit; }
img, svg { max-width: 100%; }

.container { width: min(var(--max), calc(100% - 40px)); margin: 0 auto; }
.section { padding: 88px 0; position: relative; }
.eyebrow { color: var(--blue); letter-spacing: .18em; font-size: .76rem; font-weight: 800; text-transform: uppercase; }
.gradient-text { background: linear-gradient(90deg, #fff, #7ce7ff 48%, #b9ff9e); -webkit-background-clip: text; background-clip: text; color: transparent; }
h1, h2, h3 { margin: 0; line-height: 1.05; letter-spacing: -.04em; }
h1 { font-size: clamp(3rem, 7vw, 6.8rem); max-width: 980px; }
h2 { font-size: clamp(2.1rem, 4vw, 4.2rem); }
h3 { font-size: clamp(1.25rem, 2vw, 1.75rem); }
p { color: var(--muted); margin: 0; }
.lead { font-size: clamp(1.05rem, 1.6vw, 1.32rem); max-width: 760px; }

.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  backdrop-filter: blur(18px);
  background: rgba(8, 20, 33, .78);
  border-bottom: 1px solid var(--line);
}
.navbar { height: 78px; display: flex; align-items: center; justify-content: space-between; gap: 24px; }
.logo { display: inline-flex; align-items: center; gap: 12px; font-weight: 900; letter-spacing: -.03em; font-size: 1.15rem; }
.logo-mark { width: 38px; height: 38px; border-radius: 12px; background: linear-gradient(135deg, var(--blue), var(--green)); display: grid; place-items: center; box-shadow: 0 0 30px rgba(0, 180, 216, .35); }
.logo-mark::after { content: ""; width: 18px; height: 18px; border: 3px solid #06101a; border-top-color: transparent; border-radius: 50%; transform: rotate(-35deg); }
.nav-links { display: flex; align-items: center; gap: 8px; }
.nav-link, .drop-trigger { color: #d6e6f6; padding: 10px 13px; border-radius: 999px; font-size: .94rem; background: transparent; border: 0; cursor: pointer; }
.nav-link:hover, .drop-trigger:hover { background: rgba(255,255,255,.06); color: #fff; }
.dropdown { position: relative; }
.dropdown-menu { position: absolute; top: calc(100% + 12px); left: 0; min-width: 235px; padding: 10px; background: rgba(12, 28, 46, .98); border: 1px solid var(--line); border-radius: 18px; box-shadow: var(--shadow); opacity: 0; transform: translateY(8px); pointer-events: none; transition: .22s ease; }
.dropdown:hover .dropdown-menu, .dropdown:focus-within .dropdown-menu { opacity: 1; transform: translateY(0); pointer-events: auto; }
.dropdown-menu a { display: block; padding: 12px 14px; color: var(--muted); border-radius: 12px; }
.dropdown-menu a:hover { background: rgba(0,180,216,.12); color: #fff; }
.mobile-toggle { display: none; background: rgba(255,255,255,.08); color: #fff; border: 1px solid var(--line); border-radius: 12px; padding: 9px 11px; }

.btn { display: inline-flex; align-items: center; justify-content: center; gap: 10px; min-height: 48px; padding: 0 20px; border-radius: 999px; border: 1px solid transparent; font-weight: 800; cursor: pointer; transition: .2s ease; }
.btn-primary { background: linear-gradient(135deg, var(--blue), var(--blue-2)); color: #fff; box-shadow: 0 15px 45px rgba(0, 180, 216, .24); }
.btn-primary:hover { transform: translateY(-2px); box-shadow: 0 22px 60px rgba(0, 180, 216, .35); }
.btn-secondary { border-color: var(--line); background: rgba(255,255,255,.06); color: #fff; }
.btn-secondary:hover { background: rgba(255,255,255,.1); border-color: rgba(0,180,216,.55); }

.hero { padding: 100px 0 70px; overflow: hidden; }
.hero-grid { display: grid; grid-template-columns: 1.08fr .92fr; gap: 48px; align-items: center; }
.hero-copy { display: grid; gap: 28px; }
.hero-actions { display: flex; flex-wrap: wrap; gap: 14px; }
.hero-metrics { display: flex; flex-wrap: wrap; gap: 12px; }
.metric-chip { padding: 12px 15px; border: 1px solid var(--line); border-radius: 16px; background: rgba(255,255,255,.045); color: #dff5ff; }
.metric-chip strong { color: var(--green); }

.visual-card { position: relative; min-height: 480px; border: 1px solid var(--line); border-radius: 34px; background: linear-gradient(145deg, rgba(21,41,90,.82), rgba(13,27,42,.9)); box-shadow: var(--shadow); overflow: hidden; }
.visual-card::before { content: ""; position: absolute; inset: 0; background-image: linear-gradient(rgba(255,255,255,.04) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,.04) 1px, transparent 1px); background-size: 38px 38px; mask-image: radial-gradient(circle at 50% 44%, #000, transparent 72%); }
.map-line { position: absolute; inset: 64px 38px 110px; border: 2px solid rgba(0,180,216,.22); border-radius: 48% 42% 54% 46%; transform: rotate(-10deg); }
.node { position: absolute; width: 92px; height: 92px; border: 1px solid rgba(124,231,255,.35); border-radius: 28px; background: rgba(8,20,33,.86); display: grid; place-items: center; text-align: center; font-size: .78rem; font-weight: 800; color: #fff; box-shadow: 0 0 45px rgba(0,180,216,.18); }
.node::before { content: attr(data-value); display: block; color: var(--green); font-size: 1.35rem; }
.node-a { left: 11%; top: 17%; } .node-b { right: 10%; top: 28%; } .node-c { left: 23%; bottom: 18%; } .node-d { right: 21%; bottom: 15%; }
.flow-panel { position: absolute; left: 34px; right: 34px; bottom: 32px; padding: 18px; border: 1px solid var(--line); border-radius: 22px; background: rgba(6, 16, 26, .78); backdrop-filter: blur(10px); }
.flow-bars { display: grid; gap: 9px; margin-top: 12px; }
.flow-bars span { height: 9px; border-radius: 999px; background: linear-gradient(90deg, var(--blue), transparent); opacity: .85; }
.flow-bars span:nth-child(2) { width: 78%; background: linear-gradient(90deg, var(--green), transparent); }
.flow-bars span:nth-child(3) { width: 58%; }

.product-banner { margin-top: -10px; }
.banner-card { display: flex; justify-content: space-between; align-items: center; gap: 28px; padding: 26px; border: 1px solid rgba(108,194,74,.34); border-radius: var(--radius); background: linear-gradient(90deg, rgba(108,194,74,.12), rgba(0,180,216,.1)); }

.section-head { display: flex; justify-content: space-between; gap: 28px; align-items: end; margin-bottom: 36px; }
.section-head p { max-width: 710px; }
.card-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; }
.card { position: relative; padding: 24px; border: 1px solid var(--line); border-radius: var(--radius); background: rgba(255,255,255,.045); box-shadow: 0 14px 36px rgba(0,0,0,.15); transition: .22s ease; overflow: hidden; }
.card::after { content: ""; position: absolute; inset: auto 0 0; height: 3px; background: linear-gradient(90deg, var(--blue), var(--green)); transform: scaleX(0); transform-origin: left; transition: .25s ease; }
.card:hover, .card:focus-within { transform: translateY(-5px); border-color: rgba(0,180,216,.42); background: rgba(255,255,255,.065); }
.card:hover::after { transform: scaleX(1); }
.card-icon { width: 46px; height: 46px; display: grid; place-items: center; border-radius: 15px; background: rgba(0,180,216,.13); color: var(--blue); margin-bottom: 18px; font-size: 1.35rem; }
.card h3 { margin-bottom: 12px; font-size: 1.2rem; }
.card button.fake-link { position: absolute; inset: 0; opacity: 0; cursor: pointer; border: 0; background: transparent; }
.card-detail { margin-top: 20px; padding: 16px; border: 1px solid var(--line); border-radius: 18px; background: rgba(0,180,216,.08); display: none; }
.card.is-open .card-detail { display: block; }

.tabs { display: flex; flex-wrap: wrap; gap: 10px; padding: 8px; border: 1px solid var(--line); background: rgba(255,255,255,.045); border-radius: 999px; width: fit-content; max-width: 100%; }
.tab-btn { border: 0; background: transparent; color: var(--muted); padding: 11px 18px; border-radius: 999px; cursor: pointer; font-weight: 800; transition: .2s ease; }
.tab-btn.active { background: linear-gradient(135deg, var(--blue), var(--blue-2)); color: #fff; box-shadow: 0 10px 25px rgba(0,180,216,.25); }
.tab-panel { display: none; animation: fadeUp .28s ease both; }
.tab-panel.active { display: block; }
@keyframes fadeUp { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
.industry-wrap { display: grid; gap: 24px; }
.industry-panel { border: 1px solid var(--line); border-radius: 28px; background: linear-gradient(135deg, rgba(21,41,90,.52), rgba(0,180,216,.07)); padding: 30px; display: grid; grid-template-columns: 1fr 1fr; gap: 28px; align-items: center; }
.check-list { display: grid; gap: 13px; list-style: none; padding: 0; margin: 0; }
.check-list li { color: #d7e8f8; display: flex; gap: 10px; align-items: flex-start; }
.check-list li::before { content: "✓"; color: var(--green); font-weight: 900; }

.ecosystem { position: relative; min-height: 520px; border: 1px solid var(--line); border-radius: 34px; background: radial-gradient(circle at center, rgba(0,180,216,.16), rgba(21,41,90,.15) 38%, rgba(255,255,255,.035)); overflow: hidden; }
.ecosystem .core { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); width: 190px; height: 190px; border-radius: 50%; display: grid; place-items: center; text-align: center; background: linear-gradient(135deg, var(--blue-2), var(--panel-2)); border: 1px solid rgba(124,231,255,.45); box-shadow: 0 0 80px rgba(0,180,216,.35); font-weight: 900; }
.eco-item { position: absolute; width: 220px; padding: 18px; border: 1px solid var(--line); border-radius: 22px; background: rgba(8,20,33,.88); }
.eco-item h3 { font-size: 1.05rem; margin-bottom: 8px; }
.eco-1 { left: 8%; top: 13%; } .eco-2 { right: 8%; top: 17%; } .eco-3 { left: 50%; bottom: 8%; transform: translateX(-50%); }
.ecosystem svg { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; }

.split { display: grid; grid-template-columns: 1fr 1fr; gap: 28px; align-items: stretch; }
.panel { border: 1px solid var(--line); border-radius: var(--radius); background: rgba(255,255,255,.045); padding: 30px; }
.panel.highlight { background: linear-gradient(135deg, rgba(0,180,216,.14), rgba(108,194,74,.1)); }

.benefit-list { display: grid; grid-template-columns: repeat(5, 1fr); gap: 14px; }
.benefit { padding: 22px; border: 1px solid var(--line); border-radius: 22px; background: rgba(255,255,255,.045); }
.benefit strong { display: block; color: #fff; margin-bottom: 8px; }
.stats-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 22px; }
.stat-circle { aspect-ratio: 1; max-width: 290px; margin: auto; border-radius: 50%; display: grid; place-items: center; text-align: center; padding: 28px; background: conic-gradient(from 180deg, var(--blue), var(--green), rgba(255,255,255,.08), var(--blue)); position: relative; }
.stat-circle::before { content: ""; position: absolute; inset: 9px; border-radius: inherit; background: #0b1928; }
.stat-circle > * { position: relative; }
.stat-circle strong { font-size: clamp(2.4rem, 5vw, 4.4rem); line-height: 1; color: #fff; }
.timeline { display: grid; gap: 18px; }
.timeline-row { display: grid; grid-template-columns: 150px 1fr; gap: 18px; align-items: center; padding: 18px; border: 1px solid var(--line); border-radius: 20px; background: rgba(255,255,255,.04); }
.timeline-row strong { color: var(--blue); letter-spacing: .08em; }
.progress { height: 12px; background: rgba(255,255,255,.08); border-radius: 999px; overflow: hidden; margin-top: 10px; }
.progress span { display: block; height: 100%; background: linear-gradient(90deg, var(--green), var(--blue)); border-radius: inherit; }
.accordion { display: grid; gap: 12px; }
.accordion-item { border: 1px solid var(--line); border-radius: 20px; background: rgba(255,255,255,.04); overflow: hidden; }
.accordion-trigger { width: 100%; border: 0; background: transparent; color: #fff; padding: 20px 22px; display: flex; justify-content: space-between; align-items: center; cursor: pointer; font-weight: 900; text-align: left; }
.accordion-trigger span { color: var(--blue); font-size: 1.3rem; transition: .2s ease; }
.accordion-item.active .accordion-trigger span { transform: rotate(45deg); }
.accordion-panel { max-height: 0; overflow: hidden; transition: max-height .28s ease; }
.accordion-panel p { padding: 0 22px 22px; }
.lifecycle { min-height: 520px; position: relative; border: 1px solid var(--line); border-radius: 34px; background: rgba(255,255,255,.035); overflow: hidden; }
.life-step { position: absolute; width: 180px; padding: 16px; border: 1px solid rgba(0,180,216,.35); border-radius: 20px; background: rgba(8,20,33,.88); text-align: center; }
.life-step strong { display: block; color: #fff; }
.life-1 { left: 7%; top: 13%; } .life-2 { right: 12%; top: 15%; } .life-3 { right: 8%; bottom: 18%; } .life-4 { left: 10%; bottom: 16%; }
.life-center { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); width: 210px; height: 210px; border-radius: 50%; display: grid; place-items: center; text-align: center; background: radial-gradient(circle, rgba(0,180,216,.28), rgba(21,41,90,.8)); border: 1px solid var(--line); font-weight: 900; }
.lifecycle svg { position: absolute; inset: 0; width: 100%; height: 100%; }
.carousel { overflow: hidden; }
.testimonial-track { display: flex; transition: transform .35s ease; }
.testimonial { flex: 0 0 100%; padding: 30px; border: 1px solid var(--line); border-radius: var(--radius); background: rgba(255,255,255,.045); }
.quote { font-size: clamp(1.35rem, 2.6vw, 2.25rem); color: #fff; line-height: 1.2; }
.dots { display: flex; gap: 10px; justify-content: center; margin-top: 18px; }
.dot { width: 12px; height: 12px; border-radius: 50%; border: 0; background: rgba(255,255,255,.25); cursor: pointer; }
.dot.active { background: var(--blue); }

.security-grid { display: grid; grid-template-columns: .9fr 1.1fr; gap: 28px; }
.feature-list { display: grid; gap: 14px; }
.feature-row { padding: 20px; border: 1px solid var(--line); border-radius: 18px; background: rgba(255,255,255,.04); display: grid; grid-template-columns: 44px 1fr; gap: 14px; }
.feature-row .badge { width: 44px; height: 44px; border-radius: 14px; display: grid; place-items: center; background: rgba(108,194,74,.13); color: var(--green); font-weight: 900; }
.integration-grid { display: grid; grid-template-columns: 380px 1fr; gap: 28px; align-items: start; }
.integration-card { min-height: 350px; border: 1px solid var(--line); border-radius: 28px; padding: 30px; background: linear-gradient(135deg, rgba(21,41,90,.5), rgba(0,180,216,.08)); }
.code-window { border: 1px solid var(--line); border-radius: 20px; overflow: hidden; background: #06101a; }
.window-bar { height: 42px; display: flex; gap: 8px; align-items: center; padding: 0 14px; background: rgba(255,255,255,.05); }
.window-bar span { width: 10px; height: 10px; border-radius: 50%; background: var(--green); opacity: .8; }
pre { margin: 0; padding: 20px; overflow: auto; color: #9ee8ff; font-size: .92rem; }

.form-shell { display: grid; grid-template-columns: .85fr 1.15fr; gap: 28px; align-items: start; }
.form-card { border: 1px solid rgba(0,180,216,.35); border-radius: 30px; padding: 30px; background: rgba(255,255,255,.055); box-shadow: var(--shadow); }
.form-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; }
.field { display: grid; gap: 7px; }
.field.full { grid-column: 1 / -1; }
label { font-weight: 800; color: #dff5ff; font-size: .9rem; }
input, select, textarea { width: 100%; border: 1px solid var(--line); background: rgba(4, 12, 20, .72); color: #fff; border-radius: 14px; padding: 13px 14px; outline: none; }
input:focus, select:focus, textarea:focus { border-color: var(--blue); box-shadow: 0 0 0 4px rgba(0,180,216,.12); }
.error { color: #ffb5b5; min-height: 18px; font-size: .82rem; }
.form-message { margin-top: 16px; padding: 14px; border-radius: 14px; display: none; }
.form-message.success { display: block; background: rgba(108,194,74,.13); color: #caffbb; border: 1px solid rgba(108,194,74,.35); }
.form-message.fail { display: block; background: rgba(255,100,100,.13); color: #ffd1d1; border: 1px solid rgba(255,100,100,.35); }

.cookie-banner { position: fixed; left: 20px; right: 20px; bottom: 20px; z-index: 60; display: none; }
.cookie-inner { max-width: 900px; margin: 0 auto; padding: 18px; border: 1px solid var(--line); border-radius: 20px; background: rgba(8,20,33,.96); backdrop-filter: blur(18px); box-shadow: var(--shadow); display: flex; gap: 18px; align-items: center; justify-content: space-between; }
.cookie-actions { display: flex; gap: 10px; flex-shrink: 0; }
.site-footer { border-top: 1px solid var(--line); background: rgba(3, 9, 15, .45); padding: 58px 0 28px; }
.footer-grid { display: grid; grid-template-columns: 1.4fr repeat(4, 1fr); gap: 28px; }
.footer-col { display: grid; align-content: start; gap: 10px; }
.footer-col h3 { font-size: .92rem; letter-spacing: .12em; text-transform: uppercase; color: #fff; }
.footer-col a { color: var(--muted); font-size: .94rem; }
.footer-col a:hover { color: var(--blue); }
.footer-bottom { margin-top: 36px; padding-top: 22px; border-top: 1px solid var(--line); display: flex; justify-content: space-between; gap: 18px; color: var(--muted); font-size: .9rem; }

@media (max-width: 980px) {
  .mobile-toggle { display: inline-flex; }
  .nav-links { position: fixed; inset: 78px 16px auto; padding: 16px; border: 1px solid var(--line); border-radius: 20px; background: rgba(8,20,33,.98); flex-direction: column; align-items: stretch; display: none; }
  .nav-links.open { display: flex; }
  .dropdown-menu { position: static; opacity: 1; transform: none; pointer-events: auto; box-shadow: none; margin-top: 6px; display: none; }
  .dropdown:focus-within .dropdown-menu, .dropdown:hover .dropdown-menu { display: block; }
  .hero-grid, .industry-panel, .split, .security-grid, .integration-grid, .form-shell { grid-template-columns: 1fr; }
  .card-grid, .stats-grid { grid-template-columns: repeat(2, 1fr); }
  .benefit-list { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .visual-card { min-height: 420px; }
}
@media (max-width: 640px) {
  .container { width: min(100% - 28px, var(--max)); }
  .section { padding: 64px 0; }
  .hero { padding: 64px 0 48px; }
  .navbar { height: 68px; }
  .nav-links { inset-top: 68px; }
  .card-grid, .stats-grid, .benefit-list, .form-grid, .footer-grid { grid-template-columns: 1fr; }
  .section-head, .banner-card, .cookie-inner, .footer-bottom { flex-direction: column; align-items: flex-start; }
  .tabs { border-radius: 20px; width: 100%; }
  .tab-btn { flex: 1 1 auto; }
  .ecosystem, .lifecycle { min-height: auto; display: grid; gap: 14px; padding: 18px; }
  .ecosystem svg, .lifecycle svg { display: none; }
  .ecosystem .core, .eco-item, .life-step, .life-center { position: static; transform: none; width: auto; height: auto; border-radius: 20px; }
  .timeline-row { grid-template-columns: 1fr; }
  .node { width: 78px; height: 78px; font-size: .68rem; }
  .visual-card { min-height: 360px; }
}
